window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7d5bdf3fa36d284b"]={"versions": [{"id": "FIG-7d5bdf3fa36d284b", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- und Methodikdiagramm gemäß der AUTOSAR-Methodologie-Notation zur Darstellung des Teilprozesses „Configure Debug“. Der Prozess ist in den Entwurfs- und Integrationsablauf der AUTOSAR Classic Platform eingebettet und beschreibt die methodischen Schritte zur Parametrierung des Debugging-Moduls auf ECU-Ebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktivität</strong>:</li>\n<li><code>Configure Debug</code>: Zentrale Methodik-Aktivität zur Konfiguration der Debug-Funktionalität.</li>\n<li><strong>Rolle / Akteur</strong>:</li>\n<li><code>ECU Integrator</code>: Verantwortliche Integrationsrolle, verknüpft über die Beziehung <code>«performs»</code>.</li>\n<li><strong>Eingangs-Artefakte (<code>«input»</code>)</strong>:</li>\n<li><code>BSW Module Delivered Bundle</code> (Kardinalität <code>0..*</code>): Lieferpaket der Basissoftware-Module.</li>\n<li><code>ECU Extract</code> (Kardinalität <code>1</code>): Auszug der Systemkonfiguration für das Steuergerät.</li>\n<li><code>AUTOSAR Standardized ECU</code> (Kardinalität <code>1</code>): Standardisierte ECU-Beschreibung bzw. Konfigurationsdefinition.</li>\n<li><code>Complex Device Driver</code> (Kardinalität <code>0..1</code>): Beschreibung/Konfiguration für komplexe Treiber.</li>\n<li><strong>Ein-/Ausgangs-Artefakt (<code>«inoutput»</code>)</strong>:</li>\n<li><code>ECU Configuration Values</code> (Kardinalität <code>1</code>): Bestehende ECU-Konfigurationswerte, die durch die Aktivität eingelesen und aktualisiert bzw. um Debug-Parameter erweitert werden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der <code>ECU Integrator</code> führt den Arbeitsschritt <code>Configure Debug</code> durch.</li>\n<li>Zur Konfiguration werden die Modulpakete (<code>BSW Module Delivered Bundle</code>), der <code>ECU Extract</code>, die standardisierte ECU-Definition (<code>AUTOSAR Standardized ECU</code>) sowie optional Spezifikationen für <code>Complex Device Driver</code> als Eingangsinformationen herangezogen.</li>\n<li>Die vorhandenen <code>ECU Configuration Values</code> werden geladen, um die spezifischen Debug-Konfigurationseinstellungen zu ergänzen und als konsolidierte Konfigurationswerte zurückgeschrieben.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Aktivität definiert die methodischen Voraussetzungen zur Integration von Debugging-Support in das Steuergerät. Werkzeuge müssen sicherstellen, dass die Schnittstellen und Parameterkonsistenzen zwischen BSW-Modulen, Treibern und dem ECU-Extrakt gewahrt bleiben. Die Kardinalität <code>0..1</code> des Artefakts <code>Complex Device Driver</code> kennzeichnet diesen Eingang als optional je nach Steuergerätearchitektur.</p>"}, {"id": "FIG-3574a9a8e317851c", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- und Methodikdiagramm gemäß der AUTOSAR-Methodologie-Notation zur Darstellung des Teilprozesses „Configure Debug“. Der Prozess ist in den Entwurfs- und Integrationsablauf der AUTOSAR Classic Platform eingebettet und beschreibt die methodischen Schritte zur Parametrierung des Debugging-Moduls auf ECU-Ebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktivität</strong>:</li>\n<li><code>Configure Debug</code>: Zentrale Methodik-Aktivität zur Konfiguration der Debug-Funktionalität.</li>\n<li><strong>Rolle / Akteur</strong>:</li>\n<li><code>ECU Integrator</code>: Verantwortliche Integrationsrolle, führt die Aktivität aus (<code>«performs»</code>).</li>\n<li><strong>Eingangs-Artefakte (<code>«input»</code>)</strong>:</li>\n<li><code>BSW Module Delivered Bundle</code> (Kardinalität <code>0..*</code>): Lieferpaket der Basissoftware-Module.</li>\n<li><code>ECU Extract</code> (Kardinalität <code>1</code>): Auszug der Systemkonfiguration für das Steuergerät.</li>\n<li><code>AUTOSAR Standardized ECU</code> (Kardinalität <code>1</code>): Standardisierte ECU-Beschreibung bzw. Konfigurationsdefinition.</li>\n<li><code>Complex Driver</code> (Kardinalität <code>0..1</code>): Beschreibung/Konfiguration für komplexe Treiber.</li>\n<li><strong>Ein-/Ausgangs-Artefakt (<code>«inoutput»</code>)</strong>:</li>\n<li><code>ECU Configuration Values</code> (Kardinalität <code>1</code>): Bestehende ECU-Konfigurationswerte, die durch die Aktivität eingelesen und aktualisiert bzw. um Debug-Parameter erweitert werden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der <code>ECU Integrator</code> führt den Arbeitsschritt <code>Configure Debug</code> aus.</li>\n<li>Zur Konfiguration werden die Modulpakete (<code>BSW Module Delivered Bundle</code>), der <code>ECU Extract</code>, die standardisierte ECU-Definition (<code>AUTOSAR Standardized ECU</code>) sowie optional Spezifikationen für <code>Complex Driver</code> als Eingangsinformationen herangezogen.</li>\n<li>Die vorhandenen <code>ECU Configuration Values</code> werden geladen, um die spezifischen Debug-Konfigurationseinstellungen zu ergänzen und als konsolidierte Konfigurationswerte zurückgeschrieben.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Aktivität definiert die methodischen Voraussetzungen zur Integration von Debugging-Support in das Steuergerät. Werkzeuge müssen sicherstellen, dass die Schnittstellen und Parameterkonsistenzen zwischen BSW-Modulen, Treibern und dem ECU-Extrakt gewahrt bleiben. Die Kardinalität <code>0..1</code> des Artefakts <code>Complex Driver</code> kennzeichnet diesen Eingang als optional je nach Steuergerätearchitektur.</p>"}], "trans": [{"from": "FIG-7d5bdf3fa36d284b", "to": "FIG-3574a9a8e317851c", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Beschriftung des Eingangs-Artefakts unten rechts geändert von „Complex Device Driver“ zu „Complex Driver“.</li>\n<li>Pfeilspitze der Assoziation «performs» zwischen „ECU Integrator“ und der Aktivität „Configure Debug“ umgedreht: zeigt nun vom Akteur auf die Aktivität (statt von der Aktivität zum Akteur).</li>\n</ul>"}]};
